/// The prior-release hashes recorded for `rel`, or an empty slice when the path has no row
/// (new path, or unchanged across the whole window). An empty slice is the NO-ROW case and
/// the migration must repair nothing and report - never guess.
pub fn prev_vendor_hashes(rel: &str) -> &'static [&'static str] {
    match PREV_VENDOR_HASHES.binary_search_by(|(r, _)| (*r).cmp(rel)) {
        Ok(i) => PREV_VENDOR_HASHES[i].1,
        Err(_) => &[],
    }
}
